static const UiGlyph kCarts[] = {
  { "GBA", 440, 252, kGBA },
  { "GBC", 260, 296, kGBC },
  { "GB", 260, 296, kGB },
  { 0, 0, 0, 0 }
};

const UiGlyph *uiCartImage(const char *name)
{
  for (const UiGlyph *g = kCarts; g->name; g++)
    if (strcmp(g->name, name) == 0)
      return g;
  return 0;
}
